#include <stdio.h>
#include <string.h>

int main(void) {
    char a[] = "cat";                     /* {'c','a','t','\0'}: size 4. */
    char b[3] = {'c', 'a', 't'};           /* NOT a string: no terminator. */
    char c[10] = "cat";                   /* capacity 10, length 3, rest '\0'. */
    const char *lit = "cat";              /* points at a read-only literal. */

    printf("%zu %zu\n", sizeof a, strlen(a));   /* 4 3. */
    printf("%zu %zu\n", sizeof c, strlen(c));   /* 10 3. */
    /* printf("%s", b);  undefined: reads past b looking for '\0'. */
    /* lit[0] = 'b';     undefined: literals are read-only. */
    a[0] = 'b';                            /* fine: a is a modifiable copy. */
    puts(a);                               /* bat. */
    return 0;
}
```

| | Meaning |
|---|---|
| length (strlen). | chars before the first '\0'. |
| capacity (sizeof array). | bytes the array can hold. |
| rule. | capacity >= length + 1. |

